/**
 * Job handler: SyncCarrierTracking.
 *
 * The job's only body. Every caller runs it through runSyncCarrierTrackingJob(): the
 * in-process scheduler passes its own ModuleRef, and a host with no Nest
 * injector of its own (an Azure Functions timer) passes none, so the job
 * resolves its dependencies from the jobs runtime context -- the same database
 * modules, and therefore the same database login, the service itself uses.
 * Timeout, retry and dead-letter routing wrap the body here, once.
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
import { Injectable, Logger } from '@nestjs/common';
import type { ModuleRef } from '@nestjs/core';
import { JOB_CONFIGS } from '../config';
import { jobsRuntimeModuleRef } from '../runtime';
import { EntityRepository } from '@mikro-orm/core';
import { InjectRepository } from '@mikro-orm/nestjs';
import { Shipment } from '../../ecommerce_shipping_service/entities/shipping_db/shipment.entity';
import { ShipmentStatus } from '../../enums/shipment-status.enum'
import { ShippingCarrier } from '../../enums/shipping-carrier.enum'
import { SqlEntityManager } from '@mikro-orm/postgresql';
import { subDays } from 'date-fns';
import { syncFedExTracking } from '../../functions';
import { syncUpsTracking } from '../../functions';

@Injectable()
export class SyncCarrierTrackingJob {
  private readonly logger = new Logger('SyncCarrierTrackingJob');

  constructor(
    @InjectRepository(Shipment) private readonly shipmentRepository: EntityRepository<Shipment>,
  ) {}

  async execute(): Promise<void> {
    const config = JOB_CONFIGS['SyncCarrierTracking'];
    const startTime = Date.now();
    this.logger.log('job_started name=SyncCarrierTracking');

    let lastError: Error | undefined;
    for (let attempt = 1; attempt <= config.maxAttempts; attempt++) {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), config.timeoutSeconds * 1000);
      try {
        let activeShipments: Shipment[] = await (this.shipmentRepository.getEntityManager() as SqlEntityManager).createQueryBuilder(Shipment, 'e_shipment').select('*').andWhere({ status: { $in: [ShipmentStatus.PickedUp, ShipmentStatus.InTransit, ShipmentStatus.OutForDelivery] } }).where('e_shipment.created_at > ?', [subDays(new Date(), 30)]).getResultList();
        for (const shipment of activeShipments) {
          try {
            if ((shipment.carrier === ShippingCarrier.FedEx)) {
              await syncFedExTracking(shipment);
            } else if ((shipment.carrier === ShippingCarrier.Ups)) {
              await syncUpsTracking(shipment);
            }
          }
          catch (__caught: unknown) {
            {
              const e = __caught as Error;
              console.error('failed_to_sync_tracking');
            }
          }
        }
        console.info('carrier_tracking_sync_complete');
        clearTimeout(timeoutId);
        const durationMs = Date.now() - startTime;
        this.logger.log(`job_completed name=SyncCarrierTracking duration_ms=${durationMs}`);
        return;
      } catch (error: unknown) {
        clearTimeout(timeoutId);
        lastError = error instanceof Error ? error : new Error(String(error));
        if (attempt < config.maxAttempts) {
          const delay = 1000;
          this.logger.warn(
            `job_retry name=SyncCarrierTracking attempt=${attempt} max=${config.maxAttempts}`,
          );
          await new Promise<void>(resolve => setTimeout(resolve, delay));
          continue;
        }
      }
    }

    const durationMs = Date.now() - startTime;
    const message = lastError?.message ?? 'unknown';
    this.logger.error(
      `job_failed name=SyncCarrierTracking duration_ms=${durationMs} error=${message}`,
    );
  }
}

/**
 * Run SyncCarrierTracking once.
 *
 * @param moduleRef The caller's own Nest injector; omitted by a host that has
 *   none, which then resolves the job from the jobs runtime context.
 */
export async function runSyncCarrierTrackingJob(moduleRef?: ModuleRef): Promise<void> {
  const injector = moduleRef ?? (await jobsRuntimeModuleRef());
  const job = await injector.create(SyncCarrierTrackingJob);
  await job.execute();
}
